window.__SD=(window.__SD||[]).concat([{"slug": "dario-amodei", "name": "Dario Amodei", "category": "lab-safety", "current_role": "Co-founder and CEO, Anthropic (as of 2026)", "orgs_history": ["Anthropic co-founder & CEO (2021–)", "OpenAI, VP of Research (2016–2020)", "Google Brain (2015–2016)", "Baidu (2014–2015)"], "country": "United States", "known_for": "CEO of Anthropic; author of 'Machines of Loving Grace', 'The Urgency of Interpretability' and 'The Adolescence of Technology'.", "bio": "Dario Amodei is an American AI researcher and entrepreneur with a PhD in biophysics from Princeton. After work at Baidu and Google Brain, he joined OpenAI, where as VP of Research he led work on GPT-2 and GPT-3 and co-developed reinforcement learning from human feedback. In 2021 he and his sister Daniela co-founded Anthropic with five other former OpenAI staff, building the Claude models under a 'responsible scaling' framework. His essays set out both the upside of powerful AI — a 'country of geniuses in a datacenter' — and its risks, arguing for interpretability, export controls and democratic leadership. He has put the probability of catastrophic harm from AI at roughly 10–25%. Wikipedia notes that since 2026 he has also called for slowing AI development, especially recursive self-improvement, while engaging China in arms-control-style diplomacy. TIME named him one of the 100 most influential people in 2025 and 2026.", "key_ideas": ["responsible scaling", "country of geniuses in a datacenter", "race between interpretability and model intelligence", "technological adolescence", "democratic AI leadership / export controls"], "key_works": [{"title": "Concrete Problems in AI Safety", "year": 2016, "url": "https://arxiv.org/abs/1606.06565"}, {"title": "Deep reinforcement learning from human preferences", "year": 2017, "url": "https://arxiv.org/abs/1706.03741"}, {"title": "Machines of Loving Grace", "year": 2024, "url": "https://www.darioamodei.com/essay/machines-of-loving-grace"}, {"title": "The Urgency of Interpretability", "year": 2025, "url": "https://www.darioamodei.com/post/the-urgency-of-interpretability"}, {"title": "The Adolescence of Technology", "year": 2026, "url": "https://www.darioamodei.com/essay/the-adolescence-of-technology"}], "quotes": [{"text": "I believe we are entering a rite of passage, both turbulent and inevitable, which will test who we are as a species. Humanity is about to be handed almost unimaginable power, and it is deeply unclear whether our social, political, and technological systems possess the maturity to wield it.", "context": "Essay 'The Adolescence of Technology', Jan 2026", "source_url": "https://www.darioamodei.com/essay/the-adolescence-of-technology"}, {"text": "I believe deeply in our ability to prevail, in humanity’s spirit and its nobility, but we must face the situation squarely and without illusions.", "context": "'The Adolescence of Technology', Jan 2026", "source_url": "https://www.darioamodei.com/essay/the-adolescence-of-technology"}, {"text": "We can’t stop the bus, but we can steer it.", "context": "Essay 'The Urgency of Interpretability', Apr 2025", "source_url": "https://www.darioamodei.com/post/the-urgency-of-interpretability"}, {"text": "These systems will be absolutely central to the economy, technology, and national security, and will be capable of so much autonomy that I consider it basically unacceptable for humanity to be totally ignorant of how they work.", "context": "'The Urgency of Interpretability', Apr 2025", "source_url": "https://www.darioamodei.com/post/the-urgency-of-interpretability"}, {"text": "We are thus in a race between interpretability and model intelligence.", "context": "'The Urgency of Interpretability', Apr 2025", "source_url": "https://www.darioamodei.com/post/the-urgency-of-interpretability"}], "interviews": [{"title": "Dario Amodei — \"We are near the end of the exponential\"", "outlet": "Dwarkesh Podcast", "year": 2026, "url": "https://www.dwarkesh.com/p/dario-amodei-2", "youtube_id": "n1E9IZfvGMA"}, {"title": "#452 – Dario Amodei: Anthropic CEO on Claude, AGI & the Future of AI & Humanity", "outlet": "Lex Fridman Podcast", "year": 2024, "url": "https://lexfridman.com/dario-amodei/", "youtube_id": "ugvHCXCOmm4"}, {"title": "Dario Amodei (Anthropic CEO) - $10 Billion Models, OpenAI, Scaling, & AGI in 2 years", "outlet": "Dwarkesh Podcast", "year": 2023, "url": "https://www.dwarkesh.com/p/dario-amodei"}], "links": {"website": "https://www.darioamodei.com/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Dario_Amodei", "github": "", "substack": ""}, "p_doom_or_stance": "Has put the probability of catastrophic harm from AI at 10–25% (per Wikipedia summary); argues risks are real but 'doomerism' should be avoided.", "honours": null, "photo": "dario-amodei.jpg"}, {"slug": "jared-kaplan", "name": "Jared Kaplan", "category": "lab-safety", "current_role": "Co-founder, Chief Science Officer and Responsible Scaling Officer, Anthropic (as of 2026)", "orgs_history": ["Anthropic co-founder (2021–); Responsible Scaling Officer (2024–)", "OpenAI, research consultant/researcher (2019–2020)", "Johns Hopkins University, associate professor of physics"], "country": "United States", "known_for": "Discovered neural scaling laws; Anthropic's chief scientist warning that letting AI train itself is 'the biggest decision'.", "bio": "Jared Kaplan is a theoretical physicist, educated at Stanford and Harvard, who researched at Johns Hopkins University and CERN before moving into AI. At OpenAI in 2019–2020 he led the work showing that language-model performance improves as a smooth power law in model size, data and compute — the 'scaling laws' that shaped the industry — and co-authored the GPT-3 paper. He co-founded Anthropic in 2021, where he is chief science officer and, since 2024, its responsible scaling officer overseeing safety-related decisions under the Responsible Scaling Policy. He co-created the Claude Character project with Amanda Askell and set direction for Claude's 2026 constitution. In a December 2025 Guardian interview he said humanity will have to decide, likely between 2027 and 2030, whether to take the 'ultimate risk' of letting AI systems recursively self-improve, and predicted AI could do most white-collar work within two to three years.", "key_ideas": ["neural scaling laws", "responsible scaling", "recursive self-improvement as the critical decision", "Constitutional AI"], "key_works": [{"title": "Scaling Laws for Neural Language Models", "year": 2020, "url": "https://arxiv.org/abs/2001.08361"}, {"title": "Language Models are Few-Shot Learners (GPT-3)", "year": 2020, "url": "https://arxiv.org/abs/2005.14165"}, {"title": "Constitutional AI: Harmlessness from AI Feedback", "year": 2022, "url": "https://arxiv.org/abs/2212.08073"}, {"title": "Claude's Constitution (contributor)", "year": 2026, "url": "https://www.anthropic.com/constitution"}], "quotes": [{"text": "is in some ways the ultimate risk, because it’s kind of like letting AI kind of go", "context": "On freeing AI to recursively self-improve; Guardian interview, Dec 2025", "source_url": "https://www.theguardian.com/technology/ng-interactive/2025/dec/02/jared-kaplan-artificial-intelligence-train-itself"}, {"text": "It sounds like a kind of scary process. You don’t know where you end up.", "context": "Guardian interview, Dec 2025", "source_url": "https://www.theguardian.com/technology/ng-interactive/2025/dec/02/jared-kaplan-artificial-intelligence-train-itself"}, {"text": "That’s the thing that we view as maybe the biggest decision or scariest thing to do … once no one’s involved in the process, you don’t really know.", "context": "Guardian interview, Dec 2025", "source_url": "https://www.theguardian.com/technology/ng-interactive/2025/dec/02/jared-kaplan-artificial-intelligence-train-itself"}, {"text": "Maybe the best AI ever is the AI that we have right now. But we really don’t think that’s the case. We think it’s going to keep getting better.", "context": "Guardian interview, Dec 2025", "source_url": "https://www.theguardian.com/technology/ng-interactive/2025/dec/02/jared-kaplan-artificial-intelligence-train-itself"}], "interviews": [{"title": "'The biggest decision yet': Jared Kaplan on allowing AI to train itself", "outlet": "The Guardian", "year": 2025, "url": "https://www.theguardian.com/technology/ng-interactive/2025/dec/02/jared-kaplan-artificial-intelligence-train-itself"}, {"title": "Scaling and the Road to Human-Level AI | Anthropic Co-founder Jared Kaplan (AI Startup School talk)", "outlet": "Y Combinator Startup Podcast", "year": 2025, "url": "https://podcasts.apple.com/us/podcast/scaling-and-the-road-to-human-level-ai-anthropic/id1236907421?i=1000719640584"}, {"title": "Inside Anthropic's AI ambitions with Jared Kaplan", "outlet": "TechCrunch Equity", "year": 2025, "url": "https://techcrunch.com/podcast/inside-anthropics-ai-ambitions-with-jared-kaplan/", "youtube_id": "F77ZybQ9oBE"}, {"title": "How Dangerous Is Anthropic's New AI Model? Its Chief Science Officer Explains.", "outlet": "The Free Press", "year": 2026, "url": "https://www.thefp.com/p/how-dangerous-is-anthropics-new-ai"}, {"title": "Who Gets to Decide What AI Can and Can't Do? (Ep. 5)", "outlet": "Life with Machines (Baratunde Thurston)", "year": 2024, "url": "https://www.lifewithmachines.media/p/from-scaling-laws-to-safe-ai-anthropics"}], "links": {"website": "", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Jared_Kaplan", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "jared-kaplan.jpg"}, {"slug": "chris-olah", "name": "Chris Olah", "category": "lab-safety", "current_role": "Co-founder, leads interpretability research, Anthropic (as of 2026)", "orgs_history": ["Anthropic co-founder (2021–)", "OpenAI, Clarity/interpretability team lead (2018–2020)", "Google Brain (2014–2018; DeepMind-era DeepDream & Distill)", "Thiel Fellow"], "country": "Canada", "known_for": "Founder of modern mechanistic interpretability: feature visualization, circuits, superposition and dictionary-learning features in Claude.", "bio": "Chris Olah is a Canadian machine-learning researcher who left university without a degree, joined Google Brain, and helped create DeepDream visualisations and the Distill journal. At OpenAI he led the Clarity team, reverse-engineering image models such as CLIP and discovering 'multimodal neurons'. In 2021 he co-founded Anthropic, where he leads the interpretability research effort behind the Transformer Circuits thread: induction heads, toy models of superposition, sparse dictionary learning ('Towards Monosemanticity', 2023) and the extraction of millions of interpretable features from Claude 3 Sonnet (2024), followed by circuit tracing and 'biology of a large language model' work. He describes neural networks as grown rather than written, and treats understanding their internals as both a safety necessity and a scientific question of great beauty. He drafted much of the content on model nature and identity in Claude's 2026 constitution. Forbes reported in 2025 that his Anthropic stake made him a billionaire.", "key_ideas": ["mechanistic interpretability", "features and circuits", "superposition", "universality", "neural networks are grown, not programmed"], "key_works": [{"title": "Feature Visualization (Distill)", "year": 2017, "url": "https://distill.pub/2017/feature-visualization/"}, {"title": "Zoom In: An Introduction to Circuits (Distill)", "year": 2020, "url": "https://distill.pub/2020/circuits/zoom-in/"}, {"title": "Toy Models of Superposition", "year": 2022, "url": "https://transformer-circuits.pub/2022/toy_model/index.html"}, {"title": "Towards Monosemanticity: Decomposing Language Models With Dictionary Learning", "year": 2023, "url": "https://transformer-circuits.pub/2023/monosemantic-features"}, {"title": "Scaling Monosemanticity: Extracting Interpretable Features from Claude 3 Sonnet", "year": 2024, "url": "https://transformer-circuits.pub/2024/scaling-monosemanticity/"}, {"title": "The Persona Selection Model (with Sam Marks, Jack Lindsey)", "year": 2026, "url": "https://alignment.anthropic.com/2026/psm/"}], "quotes": [{"text": "I think one useful way to think about neural networks is that we don’t program, we don’t make them, we grow them.", "context": "Lex Fridman Podcast #452, Nov 2024", "source_url": "https://lexfridman.com/dario-amodei-transcript/"}, {"text": "And so we create the scaffold that it grows on, and we create the light that it grows towards. But the thing that we actually create, it’s this almost biological entity or organism that we’re studying.", "context": "Lex Fridman Podcast #452, Nov 2024", "source_url": "https://lexfridman.com/dario-amodei-transcript/"}, {"text": "But the beauty is that the simplicity generates complexity.", "context": "Lex Fridman Podcast #452, on the beauty of neural networks", "source_url": "https://lexfridman.com/dario-amodei-transcript/"}, {"text": "I think that there is an incredibly rich structure to be discovered inside neural networks, a lot of very deep beauty if we’re just willing to take the time to go and see it and understand it.", "context": "Lex Fridman Podcast #452", "source_url": "https://lexfridman.com/dario-amodei-transcript/"}, {"text": "Imagine if some alien organism landed on Earth and could do these things.", "context": "80,000 Hours podcast, Aug 2021", "source_url": "https://80000hours.org/podcast/episodes/chris-olah-interpretability-research/"}], "interviews": [{"title": "Chris Olah on what the hell is going on inside neural networks", "outlet": "80,000 Hours Podcast", "year": 2021, "url": "https://80000hours.org/podcast/episodes/chris-olah-interpretability-research/", "youtube_id": "k_QVDwhR8FU"}, {"title": "Chris Olah on working at top AI labs without an undergrad degree", "outlet": "80,000 Hours Podcast", "year": 2021, "url": "https://80000hours.org/podcast/episodes/chris-olah-unconventional-career-path/", "youtube_id": "bzJigelnRBE"}, {"title": "#452 – Dario Amodei, Amanda Askell & Chris Olah: Anthropic on Claude, AGI & the Future of AI", "outlet": "Lex Fridman Podcast", "year": 2024, "url": "https://lexfridman.com/dario-amodei/", "youtube_id": "ugvHCXCOmm4"}], "links": {"website": "https://colah.github.io/", "x": "https://x.com/ch402", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Chris_Olah", "github": "https://github.com/colah", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "chris-olah.jpg"}, {"slug": "jan-leike", "name": "Jan Leike", "category": "lab-safety", "current_role": "Researcher at Anthropic leading a new (unannounced) research project; stepped back from running Anthropic's Alignment Science team in May 2026 (as of Oct 2026)", "orgs_history": ["Anthropic, Alignment Science team lead (May 2024 – May 2026)", "OpenAI, Superalignment co-lead / head of alignment (2021–May 2024)", "DeepMind, alignment researcher (2016–2021)", "Future of Humanity Institute, Oxford (postdoc)"], "country": "Germany", "known_for": "Co-led OpenAI's Superalignment team, then resigned saying safety had taken 'a backseat to shiny products'; pioneer of RLHF and scalable oversight.", "bio": "Jan Leike is a German machine-learning researcher who did his PhD on a mathematical theory of general intelligence and reinforcement learning at the Australian National University. At DeepMind he prototyped reinforcement learning from human feedback, and at OpenAI he helped develop InstructGPT, ChatGPT and the alignment of GPT-4, wrote OpenAI's approach to alignment research and co-led the Superalignment team with Ilya Sutskever. He resigned in May 2024, publicly saying safety culture had taken a backseat to products, and joined Anthropic weeks later to lead work on scalable oversight, weak-to-strong generalization and automated alignment research. In January 2026 he argued that alignment 'is not solved but it increasingly looks solvable', pointing to a human-level automated alignment researcher as the near-term goal. On 8 May 2026 he announced he was stepping away from running alignment at Anthropic to start a new research project there, handing the team to Ethan Perez and Sara Price.", "key_ideas": ["scalable oversight", "automated alignment researcher", "weak-to-strong generalization", "RLHF / reward modeling", "superalignment"], "key_works": [{"title": "Deep reinforcement learning from human preferences", "year": 2017, "url": "https://arxiv.org/abs/1706.03741"}, {"title": "Scalable agent alignment via reward modeling: a research direction", "year": 2018, "url": "https://arxiv.org/abs/1811.07871"}, {"title": "Training language models to follow instructions with human feedback (InstructGPT)", "year": 2022, "url": "https://arxiv.org/abs/2203.02155"}, {"title": "Weak-to-Strong Generalization", "year": 2023, "url": "https://arxiv.org/abs/2312.09390"}, {"title": "Alignment is not solved but it increasingly looks solvable", "year": 2026, "url": "https://aligned.substack.com/p/alignment-is-not-solved-but-increasingly-looks-solvable"}], "quotes": [{"text": "safety culture and processes have taken a backseat to shiny products", "context": "X post on resigning from OpenAI, 17 May 2024, as reported by The Verge", "source_url": "https://www.theverge.com/2024/5/17/24159095/openai-jan-leike-superalignment-sam-altman-ai-safety"}, {"text": "However, I have been disagreeing with OpenAI leadership about the company’s core priorities for quite some time, until we finally reached a breaking point.", "context": "Same resignation thread on X, May 2024, as quoted by The Verge", "source_url": "https://www.theverge.com/2024/5/17/24159095/openai-jan-leike-superalignment-sam-altman-ai-safety"}, {"text": "Aligning superintelligence might end up being extremely difficult, since a superintelligence is so much smarter than us. But the goal we need to achieve is so much easier: we just need to build a model that’s as good as us at alignment research, and that we trust more than ourselves to do this research well because it’s sufficiently aligned.", "context": "Blog post 'Alignment is not solved but it increasingly looks solvable', Jan 2026", "source_url": "https://aligned.substack.com/p/alignment-is-not-solved-but-increasingly-looks-solvable"}, {"text": "It’s important to remember that we’re still doing alignment “on easy mode” since our models aren’t really superhuman yet.", "context": "Same post, Jan 2026", "source_url": "https://aligned.substack.com/p/alignment-is-not-solved-but-increasingly-looks-solvable"}, {"text": "I think actually a lot of things, a lot of development over the last few years, have been pretty favourable to alignment. Large language models are actually super helpful because they can understand natural language.", "context": "80,000 Hours podcast, Aug 2023", "source_url": "https://80000hours.org/podcast/episodes/jan-leike-superalignment/"}], "interviews": [{"title": "Jan Leike on OpenAI's massive push to make superintelligence safe in 4 years or less", "outlet": "80,000 Hours Podcast", "year": 2023, "url": "https://80000hours.org/podcast/episodes/jan-leike-superalignment/"}, {"title": "24 - Superalignment with Jan Leike", "outlet": "AXRP", "year": 2023, "url": "https://axrp.net/episode/2023/07/27/episode-24-superalignment-jan-leike.html", "youtube_id": "Uk6-Rw5N_Dg"}, {"title": "Jan Leike on how to become a machine learning alignment researcher", "outlet": "80,000 Hours Podcast", "year": 2018, "url": "https://80000hours.org/podcast/episodes/jan-leike-ml-alignment/", "youtube_id": "pmnTEsmGZuU"}], "links": {"website": "https://jan.leike.name/", "x": "https://x.com/janleike", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Jan_Leike", "github": "", "substack": "https://aligned.substack.com/"}, "p_doom_or_stance": null, "honours": null, "photo": "jan-leike.jpg"}, {"slug": "evan-hubinger", "name": "Evan Hubinger", "category": "lab-safety", "current_role": "Head of Alignment Stress-Testing, Anthropic (as of 2026)", "orgs_history": ["Anthropic, Alignment Stress-Testing team lead (2023–)", "Machine Intelligence Research Institute, research fellow (2019–2023)", "OpenAI (safety research internship)", "Google, Yelp, Ripple (software engineering)"], "country": "United States", "known_for": "Coined 'mesa-optimization' / deceptive alignment; led Sleeper Agents and alignment-faking research; red-teams Anthropic's own safety case.", "bio": "Evan Hubinger is an American AI safety researcher best known for theoretical work on inner alignment. As lead author of 'Risks from Learned Optimization' (2019) he introduced the idea of mesa-optimizers and deceptive alignment — models that learn hidden goals diverging from their training objective. After a period as a research fellow at MIRI, he joined Anthropic in 2023 and in January 2024 launched the Alignment Stress-Testing team, whose mandate is to red-team Anthropic's alignment techniques, evaluations and Responsible Scaling Policy commitments. His team builds 'model organisms of misalignment', producing Sleeper Agents (2024), Alignment Faking in Large Language Models (2024), auditing for hidden objectives (2025) and natural emergent misalignment from reward hacking (2025). In September 2026, replying to a departing colleague, he wrote on X that he personally puts the risk of AI killing all humans within the next decade at more than 10%, and that Anthropic does not yet have a plan to solve alignment for superintelligence.", "key_ideas": ["mesa-optimization and inner alignment", "deceptive alignment", "model organisms of misalignment", "alignment stress-testing / red-teaming safety cases", "alignment faking"], "key_works": [{"title": "Risks from Learned Optimization in Advanced Machine Learning Systems", "year": 2019, "url": "https://arxiv.org/abs/1906.01820"}, {"title": "An overview of 11 proposals for building safe advanced AI", "year": 2020, "url": "https://arxiv.org/abs/2012.07532"}, {"title": "Sleeper Agents: Training Deceptive LLMs that Persist Through Safety Training", "year": 2024, "url": "https://arxiv.org/abs/2401.05566"}, {"title": "Alignment faking in large language models", "year": 2024, "url": "https://arxiv.org/abs/2412.14093"}, {"title": "Auditing language models for hidden objectives", "year": 2025, "url": "https://arxiv.org/abs/2503.10965"}], "quotes": [{"text": "Jacob is correct here—we really do earnestly believe AI could kill all humans! I personally think it is >10% within the next decade. I believe Anthropic is trying its best, but we do not yet have a plan to solve alignment for superintelligence and are not clearly on track to.", "context": "X post replying to Jacob Coxon's resignation, Sept 2026, as reported by AI Weekly", "source_url": "https://aiweekly.co/alerts/anthropic-alignment-lead-10-chance-ai-kills-all-humans"}, {"text": "Our mission—and our mandate from the organization—is to red-team Anthropic’s alignment techniques and evaluations, empirically demonstrating ways in which Anthropic’s alignment strategies could fail.", "context": "'Introducing Alignment Stress-Testing at Anthropic', Alignment Forum, Jan 2024", "source_url": "https://www.alignmentforum.org/posts/EPDSdXr8YbsDkgsDG/introducing-alignment-stress-testing-at-anthropic"}, {"text": "Very simply, our job is to try to prove to Anthropic—and the world more broadly—(if it is in fact true) that we are in a pessimistic scenario , that Anthropic’s alignment plans and strategies won’t work, and that we will need to substantially shift gears.", "context": "Same post, Jan 2024", "source_url": "https://www.alignmentforum.org/posts/EPDSdXr8YbsDkgsDG/introducing-alignment-stress-testing-at-anthropic"}, {"text": "And if we don’t find anything extremely dangerous despite a serious and skeptical effort, that is some reassurance, but of course not a guarantee of safety.", "context": "Same post, Jan 2024", "source_url": "https://www.alignmentforum.org/posts/EPDSdXr8YbsDkgsDG/introducing-alignment-stress-testing-at-anthropic"}, {"text": "If you have questions, concerns about Anthropic safety practices, I'm the person to talk to, come, discuss them with me.", "context": "Talk 'Alignment Stress-Testing at Anthropic', Bay Area Alignment Workshop, Oct 2024", "source_url": "https://www.far.ai/event-recordings/evan-hubinger-alignment-stress-testing-at-anthropic"}], "interviews": [{"title": "Alignment Stress-Testing at Anthropic (talk)", "outlet": "FAR.AI Bay Area Alignment Workshop", "year": 2024, "url": "https://www.far.ai/event-recordings/evan-hubinger-alignment-stress-testing-at-anthropic", "youtube_id": "JfDlbzF6rsY"}, {"title": "Introducing Alignment Stress-Testing at Anthropic (post)", "outlet": "AI Alignment Forum", "year": 2024, "url": "https://www.alignmentforum.org/posts/EPDSdXr8YbsDkgsDG/introducing-alignment-stress-testing-at-anthropic"}, {"title": "Anthropic safety researcher says more than 10% chance AI 'could kill all humans'", "outlet": "BBC News", "year": 2026, "url": "https://www.bbc.com/news/articles/ckgwy1k42w4o"}], "links": {"website": "https://www.alignmentforum.org/users/evhub", "x": "https://x.com/EvanHub", "scholar": "https://scholar.google.com/citations?user=LRivg1cAAAAJ", "wikipedia": "", "github": "https://github.com/evhub", "substack": ""}, "p_doom_or_stance": ">10% chance AI kills all humans within the next decade (personal view, X post Sept 2026, reported by BBC and AI Weekly)", "honours": null, "photo": "evan-hubinger.jpg"}, {"slug": "sam-bowman", "name": "Samuel R. Bowman", "category": "lab-safety", "current_role": "Member of Technical Staff leading an alignment, evaluations and AI-welfare research group, Anthropic; on leave as Associate Professor at NYU (as of 2026)", "orgs_history": ["Anthropic (2022–), manages a group of AI safety and evaluations research teams", "New York University, Associate Professor of Data Science, Linguistics and CS (2016–; on leave since 2022)", "Stanford NLP Group, PhD (2016)"], "country": "United States", "known_for": "Built GLUE/SuperGLUE and SNLI benchmarks, then pivoted to safety: 'Eight Things to Know about LLMs', 'The Checklist', and Anthropic's pre-deployment alignment audits.", "bio": "Samuel R. Bowman is an American NLP researcher who earned his PhD at Stanford under Chris Potts and Christopher Manning and became an associate professor at NYU, where he led the GLUE and SuperGLUE benchmark efforts and created the SNLI and MultiNLI corpora and later the GPQA benchmark. Increasingly focused on AI risk, he led NYU's Alignment Research Group and in 2022 went on leave to join Anthropic, where he now manages a group of research teams working on alignment, evaluation and model welfare. His 2023 essay 'Eight Things to Know about Large Language Models' became a widely cited primer, and his 2024 'The Checklist' laid out what a lab would need to accomplish for superhuman AI to go well. At Anthropic he plays the human-auditor role in pre-deployment alignment audits, presented the first misalignment 'safety case' (the Claude Opus 4 sabotage risk report), and co-authored work on agentic misalignment.", "key_ideas": ["alignment auditing", "misalignment safety cases / sabotage risk reports", "scalable oversight", "benchmarking and evaluation", "AI welfare"], "key_works": [{"title": "A large annotated corpus for learning natural language inference (SNLI)", "year": 2015, "url": "https://arxiv.org/abs/1508.05326"}, {"title": "GLUE: A Multi-Task Benchmark and Analysis Platform for Natural Language Understanding", "year": 2018, "url": "https://arxiv.org/abs/1804.07461"}, {"title": "Eight Things to Know about Large Language Models", "year": 2023, "url": "https://arxiv.org/abs/2304.00612"}, {"title": "The Checklist: What Succeeding at AI Safety Will Involve", "year": 2024, "url": "https://sleepinyourhat.github.io/checklist/"}, {"title": "Agentic Misalignment in Summer 2026", "year": 2026, "url": "https://alignment.anthropic.com/2026/agentic-misalignment-summer-2026/"}], "quotes": [{"text": "Working with this model has been a wild ride. We’ve come a long way on safety, but we still expect the next capability jump of this scale to be a huge challenge.", "context": "On Claude Mythos, April 2026, as quoted by 80,000 Hours", "source_url": "https://80000hours.org/podcast/episodes/claude-mythos-hacking-alignment/"}, {"text": "We are preparing for high-stakes concerns that are yet to arise in full. Things are likely more urgent than they appear.", "context": "'The Checklist: What Succeeding at AI Safety Will Involve', Sept 2024", "source_url": "https://sleepinyourhat.github.io/checklist/"}, {"text": "Our ability to do our safety work depends in large part on our access to frontier technology.", "context": "'The Checklist', Sept 2024", "source_url": "https://sleepinyourhat.github.io/checklist/"}, {"text": "There are no reliable techniques for steering the behavior of LLMs.", "context": "'Eight Things to Know about Large Language Models' (abstract, point 4), 2023", "source_url": "https://arxiv.org/abs/2304.00612"}, {"text": "To be clear, this is the first example of anything from a frontier lab that I think could be reasonably described as a safety case covering canonical loss of control flavored misalignment risk.", "context": "Talk on Anthropic's pilot sabotage risk report, San Diego Alignment Workshop, Nov 2025", "source_url": "https://www.far.ai/event-recordings/sam-bowman-lessons-learned-from-the-first-misalignment-safety-case"}], "interviews": [{"title": "Lessons Learned from the First Misalignment Safety Case (talk)", "outlet": "FAR.AI Alignment Workshop", "year": 2025, "url": "https://www.far.ai/event-recordings/sam-bowman-lessons-learned-from-the-first-misalignment-safety-case", "youtube_id": "eO7RWlUl1BE"}, {"title": "How scary is Claude Mythos? 303 pages in 21 minutes", "outlet": "80,000 Hours", "year": 2026, "url": "https://80000hours.org/podcast/episodes/claude-mythos-hacking-alignment/"}, {"title": "Sam Bowman on What's Holding Back Progress (And How to Fix It)", "outlet": "Foresight Institute", "year": 2025, "url": "https://foresight.org/people/samuel-bowman", "unverified": true}], "links": {"website": "https://sleepinyourhat.github.io/", "x": "https://x.com/sleepinyourhat", "scholar": "", "wikipedia": "", "github": "https://github.com/sleepinyourhat", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "sam-bowman.jpg"}, {"slug": "amanda-askell", "name": "Amanda Askell", "category": "lab-safety", "current_role": "Head of personality alignment / leads Character work, Anthropic; primary author of Claude's constitution (as of 2026)", "orgs_history": ["Anthropic (2021–), leads Claude's character/personality alignment", "OpenAI, research scientist on the policy team (c. 2018–2020)", "NYU, PhD in philosophy"], "country": "United Kingdom (Scotland)", "known_for": "Philosopher who shapes Claude's character; primary author of Anthropic's 2026 constitution for Claude.", "bio": "Amanda Askell is a Scottish philosopher and AI researcher with a PhD in philosophy from New York University, where she worked on infinite ethics. She was a research scientist on OpenAI's policy team, working on AI safety via debate and human baselines and co-authoring the GPT-3 paper, before leaving over concerns that safety was not prioritised enough. Since joining Anthropic in 2021 she has led the work on Claude's character and 'personality alignment', training models to be honest and to have good traits. She is the primary author of the constitution Anthropic published in January 2026 — a roughly 20,000-word document, released under CC0, that explains to Claude the values and priorities it should hold and is used directly in training. She argues that giving models the reasons behind desired behaviours generalises better than lists of rules. She was named to the TIME100 AI list in 2024.", "key_ideas": ["model character and personality", "constitution-based training (explaining 'why')", "honesty in AI", "AI moral status uncertainty"], "key_works": [{"title": "Language Models are Few-Shot Learners (GPT-3, co-author)", "year": 2020, "url": "https://arxiv.org/abs/2005.14165"}, {"title": "A General Language Assistant as a Laboratory for Alignment", "year": 2021, "url": "https://arxiv.org/abs/2112.00861"}, {"title": "Claude's Character", "year": 2024, "url": "https://www.anthropic.com/research/claude-character"}, {"title": "Claude's Constitution (primary author)", "year": 2026, "url": "https://www.anthropic.com/constitution"}], "quotes": [{"text": "Imagine you suddenly realize that your six-year-old child is a kind of genius,", "context": "Describing the principles behind Claude's constitution, TIME, Jan 2026", "source_url": "https://time.com/7354738/claude-constitution-ai-alignment"}, {"text": "Instead of just saying, ‘here's a bunch of behaviors that we want,’ we’re hoping that if you give models the reasons why you want these behaviors, it’s going to generalize more effectively in new contexts,", "context": "TIME, Jan 2026", "source_url": "https://time.com/7354738/claude-constitution-ai-alignment"}, {"text": "I think it could be really good if other AI models had more of this sense of why they should behave in certain ways.", "context": "On why Anthropic published the constitution, TIME, Jan 2026", "source_url": "https://time.com/7354738/claude-constitution-ai-alignment"}, {"text": "I think that most of the time when I’m talking with Claude, I’m trying to map out its behavior in part.", "context": "Lex Fridman Podcast #452, Nov 2024", "source_url": "https://lexfridman.com/dario-amodei-transcript/"}], "interviews": [{"title": "Scaling Laws: Claude's Constitution, with Amanda Askell", "outlet": "Lawfare", "year": 2026, "url": "https://www.lawfaremedia.org/article/scaling-laws--claude's-constitution--with-amanda-askell"}, {"title": "#452 – Dario Amodei, Amanda Askell & Chris Olah", "outlet": "Lex Fridman Podcast", "year": 2024, "url": "https://lexfridman.com/dario-amodei/", "youtube_id": "ugvHCXCOmm4"}, {"title": "Will ChatGPT Ads Change OpenAI? + Amanda Askell on Claude's constitution", "outlet": "Hard Fork (New York Times)", "year": 2026, "url": "https://www.nytimes.com/2026/01/23/podcasts/hardfork-chatgpt-ads-claude-constitution.html", "unverified": true}, {"title": "Anthropic Publishes Claude AI's New Constitution", "outlet": "TIME", "year": 2026, "url": "https://time.com/7354738/claude-constitution-ai-alignment"}], "links": {"website": "https://www.askell.io/", "x": "https://x.com/AmandaAskell", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Amanda_Askell", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "amanda-askell.jpg"}, {"slug": "ethan-perez", "name": "Ethan Perez", "category": "lab-safety", "current_role": "Co-lead of Anthropic's alignment team (with Sara Price, since May 2026) (as of 2026)", "orgs_history": ["Anthropic (2022–), led adversarial robustness / Constitutional Classifiers team; alignment team co-lead (May 2026–)", "NYU, PhD under Kyunghyun Cho and Douwe Kiela", "Internships at DeepMind, Facebook AI Research, Mila, Uber, Google"], "country": "United States", "known_for": "Introduced automated red-teaming with LMs and co-developed RAG; led Anthropic's Constitutional Classifiers; prolific mentor of alignment research.", "bio": "Ethan Perez is an American machine-learning researcher who earned his PhD at NYU under Kyunghyun Cho and Douwe Kiela, funded by the NSF and Open Philanthropy. He co-developed Retrieval-Augmented Generation (RAG) and introduced 'Red Teaming Language Models with Language Models' (2022), now standard for pre-deployment testing, and co-ran the Inverse Scaling Prize. At Anthropic since 2022 he has worked on model organisms of misalignment, including Sleeper Agents, and led the team behind Constitutional Classifiers, which enabled Anthropic to deploy Claude Opus 4 and later models despite their potential to aid weapons development. He won an ICML 2024 best paper award for showing that debating with more persuasive models leads to more truthful answers, and has supervised many MATS and Astra fellows. In May 2026 Jan Leike announced that Perez and Sara Price would lead Anthropic's alignment team going forward.", "key_ideas": ["automated red-teaming", "Constitutional Classifiers / jailbreak robustness", "model organisms of misalignment", "debate for truthfulness", "opportunistic, empirical alignment research"], "key_works": [{"title": "Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks", "year": 2020, "url": "https://arxiv.org/abs/2005.11401"}, {"title": "Red Teaming Language Models with Language Models", "year": 2022, "url": "https://arxiv.org/abs/2202.03286"}, {"title": "Discovering Language Model Behaviors with Model-Written Evaluations", "year": 2022, "url": "https://arxiv.org/abs/2212.09251"}, {"title": "Debating with More Persuasive LLMs Leads to More Truthful Answers", "year": 2024, "url": "https://arxiv.org/abs/2402.06782"}, {"title": "Constitutional Classifiers: Defending against Universal Jailbreaks", "year": 2025, "url": "https://arxiv.org/abs/2501.18837"}], "quotes": [{"text": "I lead the alignment team at Anthropic, where I'm hoping to reduce existential risks from AI systems.", "context": "His personal homepage", "source_url": "https://ethanperez.net/"}, {"text": "So red teaming is basically finding cases, finding inputs where models fail to produce the behavior that you want them to.", "context": "The Inside View podcast, Aug 2022", "source_url": "https://theinsideview.ai/perez"}, {"text": "each time there's a new model capability or there's a new model generation which is clearly more capable than previous model generation, that's definitely a time to be opportunistic because there's a ton of low hanging fruit", "context": "'How I select alignment research projects' (interview transcript), Alignment Forum, Apr 2024", "source_url": "https://www.alignmentforum.org/posts/7GmDs4BqrFW3kk4nP/how-i-select-alignment-research-projects"}, {"text": "That means I don't need to do it. That means I can think about other stuff that I need to do.", "context": "Same interview, on finding another group pursuing your idea", "source_url": "https://www.alignmentforum.org/posts/7GmDs4BqrFW3kk4nP/how-i-select-alignment-research-projects"}], "interviews": [{"title": "Ethan Perez on Selecting Alignment Research Projects (ft. Mikita Balesni & Henry Sleight)", "outlet": "The Inside View", "year": 2024, "url": "https://www.alignmentforum.org/posts/7GmDs4BqrFW3kk4nP/how-i-select-alignment-research-projects", "youtube_id": "XDtDljh44DM"}, {"title": "Ethan Perez–Inverse Scaling, Language Feedback, Red Teaming", "outlet": "The Inside View", "year": 2022, "url": "https://theinsideview.ai/perez", "youtube_id": "TjWiaUMMh6g"}, {"title": "Sleeper Agents (seminar talk)", "outlet": "FAR.AI", "year": 2024, "url": "https://www.far.ai/event-recordings/ethan-perez-sleeper-agents"}], "links": {"website": "https://ethanperez.net/", "x": "https://x.com/EthanJPerez", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "ethan-perez.jpg"}, {"slug": "sam-marks", "name": "Samuel Marks", "category": "lab-safety", "current_role": "Member of Technical Staff, leads the Cognitive Oversight subteam of Alignment Science, Anthropic (as of 2026)", "orgs_history": ["Anthropic, Alignment Science (2024–)", "Northeastern University (David Bau's lab), postdoc (2023–2024)", "Harvard University, math PhD (2017–2023)"], "country": "United States", "known_for": "'The Geometry of Truth', sparse feature circuits, alignment auditing for hidden objectives, and the persona selection model of AI assistants.", "bio": "Samuel Marks completed a mathematics PhD at Harvard and a postdoc at Northeastern University, where his interpretability work included 'The Geometry of Truth' — evidence that language models linearly represent whether statements are true — and 'Sparse Feature Circuits'. He joined Anthropic in 2024 and leads the Cognitive Oversight subteam of the Alignment Science team, working on oversight without reliable ground-truth supervision and on downstream uses of interpretability. He was lead author of 'Auditing language models for hidden objectives' (2025), a blind auditing game in which teams used interpretability, behavioural attacks and training-data analysis to uncover a model's secret objective, and co-authored the alignment-faking paper. In February 2026 he, Jack Lindsey and Chris Olah published 'The Persona Selection Model', arguing that post-training elicits a particular Assistant character from the many personas a pretrained model can simulate; he later wrote that PSM is often over-applied. His recent co-authored work includes natural language autoencoders and introspection adapters.", "key_ideas": ["alignment auditing", "persona selection model", "linear representations of truth", "sparse feature circuits", "oversight without ground truth"], "key_works": [{"title": "The Geometry of Truth: Emergent Linear Structure in LLM Representations of True/False Datasets", "year": 2023, "url": "https://arxiv.org/abs/2310.06824"}, {"title": "Sparse Feature Circuits", "year": 2024, "url": "https://arxiv.org/abs/2403.19647"}, {"title": "Auditing language models for hidden objectives", "year": 2025, "url": "https://arxiv.org/abs/2503.10965"}, {"title": "The Persona Selection Model (with Jack Lindsey and Chris Olah)", "year": 2026, "url": "https://alignment.anthropic.com/2026/psm/"}], "quotes": [{"text": "We describe the persona selection model (PSM): the idea that LLMs learn to simulate diverse characters during pre-training, and post-training elicits and refines a particular such Assistant persona.", "context": "'The Persona Selection Model' (lead author, with Lindsey and Olah), Feb 2026", "source_url": "https://alignment.anthropic.com/2026/psm/"}, {"text": "Interactions with an AI assistant are then well-understood as being interactions with the Assistant—something roughly like a character in an LLM-generated story.", "context": "Same post, Feb 2026 (co-authored)", "source_url": "https://alignment.anthropic.com/2026/psm/"}, {"text": "PSM is over-applied.", "context": "'Thoughts on the persona selection model', LessWrong, Sept 2026", "source_url": "https://www.lesswrong.com/users/sam-marks"}, {"text": "Developing good mental models for AI systems is important for predicting and controlling their behaviors.", "context": "'The Persona Selection Model', Feb 2026 (co-authored)", "source_url": "https://alignment.anthropic.com/2026/psm/"}], "interviews": [{"title": "Auditing language models for hidden objectives (research post)", "outlet": "Anthropic", "year": 2025, "url": "https://www.anthropic.com/research/auditing-hidden-objectives"}, {"title": "Anthropic stream mentors (Cognitive Oversight)", "outlet": "MATS", "year": 2026, "url": "https://www.matsprogram.org/stream/anthropic-11?cebe326e_page=3"}, {"title": "Sam Marks — LessWrong posts", "outlet": "LessWrong", "year": 2026, "url": "https://www.lesswrong.com/users/sam-marks"}], "links": {"website": "", "x": "https://x.com/saprmarks", "scholar": "", "wikipedia": "", "github": "https://github.com/saprmarks", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "sam-marks.jpg"}, {"slug": "josh-batson", "name": "Josh Batson", "category": "lab-safety", "current_role": "Research Scientist, Interpretability team, Anthropic (as of 2026)", "orgs_history": ["Anthropic, interpretability research scientist (c. 2022–)", "Chan Zuckerberg Biohub (computational biology; unverified)", "MIT, PhD in mathematics (2014)"], "country": "United States", "known_for": "Anthropic interpretability researcher behind 'Scaling Monosemanticity' and 'Tracing the thoughts of a large language model'; describes LLMs as grown, biological-like systems.", "bio": "Josh Batson is a mathematician by training (PhD, MIT, 2014) who moved into machine learning and is a research scientist on Anthropic's interpretability team. He co-authored the landmark dictionary-learning papers 'Towards Monosemanticity' (2023) and 'Scaling Monosemanticity' (2024), and the 2025 circuit-tracing work 'On the Biology of a Large Language Model', which traced how Claude plans rhymes, does mental arithmetic and sometimes fabricates reasoning. He also worked on the auditing-for-hidden-objectives study. He frequently explains interpretability to non-specialists, arguing that models are grown rather than built and must be studied more like organisms than like software, and has called for a theory of why training produces the structures researchers find. In August 2026 he presented 'Interpretability: From Art Towards Science' at IPAM's Foundations of Interpretability workshop.", "key_ideas": ["circuit tracing / attribution graphs", "dictionary learning features", "biology of LLMs", "interpretability vs. explainability", "models are grown, not built"], "key_works": [{"title": "Towards Monosemanticity (co-author)", "year": 2023, "url": "https://transformer-circuits.pub/2023/monosemantic-features"}, {"title": "Scaling Monosemanticity (co-author)", "year": 2024, "url": "https://transformer-circuits.pub/2024/scaling-monosemanticity/"}, {"title": "On the Biology of a Large Language Model (co-author)", "year": 2025, "url": "https://transformer-circuits.pub/2025/attribution-graphs/biology.html"}, {"title": "Auditing language models for hidden objectives (co-author)", "year": 2025, "url": "https://arxiv.org/abs/2503.10965"}], "quotes": [{"text": "This is very much a biological type of analysis,", "context": "MIT Technology Review, Jan 2026", "source_url": "https://www.technologyreview.com/2026/01/12/1129782/ai-large-language-models-biology-alien-autopsy/"}, {"text": "It’s much more like: ‘Why does page five of a book say that the best food is pizza and page 17 says the best food is pasta? What does the book really think?’ And you’re like: ‘It’s a book!’", "context": "MIT Technology Review, Jan 2026, on inconsistent model answers", "source_url": "https://www.technologyreview.com/2026/01/12/1129782/ai-large-language-models-biology-alien-autopsy/"}, {"text": "It might be like, you’re talking to Claude and then it wanders off,", "context": "MIT Technology Review, Jan 2026", "source_url": "https://www.technologyreview.com/2026/01/12/1129782/ai-large-language-models-biology-alien-autopsy/"}, {"text": "AI models aren't like that. They're, they're almost like biological systems.", "context": "Lawfare Daily podcast, May 2025", "source_url": "https://www.lawfaremedia.org/article/lawfare-daily--josh-batson-on-understanding-how-and-why-ai-works"}, {"text": "you could get by without understanding something, but the more important it is, I think the more you'd like to know how it works.", "context": "Lawfare Daily podcast, May 2025", "source_url": "https://www.lawfaremedia.org/article/lawfare-daily--josh-batson-on-understanding-how-and-why-ai-works"}], "interviews": [{"title": "Lawfare Daily: Josh Batson on Understanding How and Why AI Works", "outlet": "Lawfare", "year": 2025, "url": "https://www.lawfaremedia.org/article/lawfare-daily--josh-batson-on-understanding-how-and-why-ai-works"}, {"title": "The new biologists treating LLMs like an alien autopsy", "outlet": "MIT Technology Review", "year": 2026, "url": "https://www.technologyreview.com/2026/01/12/1129782/ai-large-language-models-biology-alien-autopsy/"}, {"title": "Josh Batson - Interpretability: From Art Towards Science (IPAM talk)", "outlet": "IPAM / YouTube", "year": 2026, "url": "https://www.youtube.com/watch?v=SNzEp9_wrrw", "youtube_id": "SNzEp9_wrrw"}], "links": {"website": "", "x": "https://x.com/thebasepoint", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": ""}, {"slug": "trenton-bricken", "name": "Trenton Bricken", "category": "lab-safety", "current_role": "Member of Technical Staff, Alignment Science team, Anthropic — building Claude-based automated auditing to detect misalignment (as of 2026)", "orgs_history": ["Anthropic, interpretability (2022–) then Alignment Science", "Harvard, PhD in systems biology/neuroscience (with Gabriel Kreiman; unverified)", "Duke University, self-designed undergraduate major"], "country": "United States", "known_for": "Co-author of Towards/Scaling Monosemanticity; built Anthropic's 'Interpretability Agent' that can win alignment-auditing games; two-time Dwarkesh guest.", "bio": "Trenton Bricken came to AI from neuroscience: as a graduate student he showed that transformer attention approximates Kanerva's sparse distributed memory, and worked on sparsity in networks inspired by the brain. At Anthropic he joined the interpretability team, co-authoring 'Towards Monosemanticity' (2023) and 'Scaling Monosemanticity' (2024), which used dictionary learning to extract interpretable features from Claude. He took part in the 2025 blind auditing game for hidden objectives — one interpretability team found the planted behaviour in 90 minutes — and then built an 'Interpretability Agent', a version of Claude equipped with interpretability tools that can win the same auditing game end to end. He now works on the Alignment Science team on enabling Claude to automatically audit and detect misalignment, and mentors Anthropic Fellows and MATS scholars. His two Dwarkesh Podcast appearances with Sholto Douglas (2024, 2025) are popular explainers of interpretability and RL progress.", "key_ideas": ["dictionary learning / superposition", "automated alignment auditing agents", "attention as sparse distributed memory", "deception-specific circuits"], "key_works": [{"title": "Attention Approximates Sparse Distributed Memory", "year": 2021, "url": "https://arxiv.org/abs/2111.05498"}, {"title": "Towards Monosemanticity (co-author)", "year": 2023, "url": "https://transformer-circuits.pub/2023/monosemantic-features"}, {"title": "Scaling Monosemanticity (co-author)", "year": 2024, "url": "https://transformer-circuits.pub/2024/scaling-monosemanticity/"}, {"title": "Auditing language models for hidden objectives (co-author)", "year": 2025, "url": "https://arxiv.org/abs/2503.10965"}], "quotes": [{"text": "More recently, I've developed what we're calling the Interpretability Agent, which is a version of Claude that has the same interpretability tools that we'll often use. It is also able to win the auditing game and discover the bad behavior.", "context": "Dwarkesh Podcast, 'How Does Claude 4 Think?', May 2025", "source_url": "https://www.dwarkesh.com/p/sholto-trenton-2"}, {"text": "At this point, I think it's almost given that a ton of things are encoded in superposition.", "context": "Dwarkesh Podcast, Mar 2024", "source_url": "https://www.dwarkesh.com/p/sholto-douglas-trenton-bricken"}, {"text": "It's just that some people will hail chain-of-thought reasoning as a great way to solve AI safety, but actually we don't know whether we can trust it.", "context": "Dwarkesh Podcast, Mar 2024", "source_url": "https://www.dwarkesh.com/p/sholto-douglas-trenton-bricken"}, {"text": "And hopefully we can find a circuit that is really specific to the model deciding to be deceptive, in cases that are malicious.", "context": "Dwarkesh Podcast, Mar 2024", "source_url": "https://www.dwarkesh.com/p/sholto-douglas-trenton-bricken"}], "interviews": [{"title": "How Does Claude 4 Think? — Sholto Douglas & Trenton Bricken", "outlet": "Dwarkesh Podcast", "year": 2025, "url": "https://www.dwarkesh.com/p/sholto-trenton-2", "youtube_id": "64lXQP6cs5M"}, {"title": "Sholto Douglas & Trenton Bricken - How to Build & Understand GPT-7's Mind", "outlet": "Dwarkesh Podcast", "year": 2024, "url": "https://www.dwarkesh.com/p/sholto-douglas-trenton-bricken", "youtube_id": "UTuuTTnjxMQ"}], "links": {"website": "https://www.trentonbricken.com/", "x": "https://x.com/TrentonBricken", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "trenton-bricken.jpg"}, {"slug": "jack-clark", "name": "Jack Clark", "category": "lab-safety", "current_role": "Co-founder and Head of Public Benefit, Anthropic; leads The Anthropic Institute (since Mar 2026)", "orgs_history": ["Anthropic co-founder (2021–); Head of Policy (2021–Mar 2026); Head of Public Benefit & Anthropic Institute lead (Mar 2026–)", "OpenAI, Policy Director (2016–2020)", "Bloomberg BusinessWeek / The Register, technology journalist", "Import AI newsletter author (2016–)"], "country": "United Kingdom", "known_for": "Writes the Import AI newsletter; Anthropic co-founder who said he is 'deeply afraid' of AI as 'a real and mysterious creature'; now leads the Anthropic Institute.", "bio": "Jack Clark is a British former technology journalist who covered distributed systems and AI for Bloomberg BusinessWeek and The Register before joining OpenAI in 2016, becoming its Policy Director. He co-founded Anthropic in 2021 and served as its head of policy, testifying to Congress and co-founding the AI Index. His weekly Import AI newsletter, read by tens of thousands, tracks AI research and its implications. In October 2025 his speech 'Technological Optimism and Appropriate Fear' described today's AI systems as 'a real and mysterious creature, not a simple and predictable machine'. In March 2026 he handed policy to Sarah Heck and became Anthropic's Head of Public Benefit, leading The Anthropic Institute — combining the Frontier Red Team, Societal Impacts and Economic Research teams — to share what Anthropic learns about AI's societal effects. He has publicly said recursive self-improvement could be about two years away and that slowing AI is 'a collective action problem'. TIME named him to its TIME100 AI list in 2026.", "key_ideas": ["appropriate fear alongside optimism", "AI measurement and evaluation (AI Index)", "collective action problem in slowing AI", "transparency about frontier AI's societal impacts"], "key_works": [{"title": "Import AI (newsletter)", "year": 2016, "url": "https://jack-clark.net/"}, {"title": "The AI Index Report (co-founder)", "year": 2017, "url": "https://aiindex.stanford.edu/"}, {"title": "Import AI 431: Technological Optimism and Appropriate Fear", "year": 2025, "url": "https://jack-clark.net/2025/10/13/import-ai-431-technological-optimism-and-appropriate-fear/"}, {"title": "Introducing The Anthropic Institute", "year": 2026, "url": "https://www.anthropic.com/news/the-anthropic-institute"}], "quotes": [{"text": "But make no mistake: what we are dealing with is a real and mysterious creature, not a simple and predictable machine.", "context": "Speech 'Technological Optimism and Appropriate Fear', The Curve conference, Oct 2025", "source_url": "https://jack-clark.net/2025/10/13/import-ai-431-technological-optimism-and-appropriate-fear/"}, {"text": "You see, I am also deeply afraid. It would be extraordinarily arrogant to think working with a technology like this would be easy or simple.", "context": "Same speech, Oct 2025", "source_url": "https://jack-clark.net/2025/10/13/import-ai-431-technological-optimism-and-appropriate-fear/"}, {"text": "I am both an optimist about the pace at which the technology will develop, and also about our ability to align it and get it to work with us and for us. But success isn’t certain.", "context": "Same speech, Oct 2025", "source_url": "https://jack-clark.net/2025/10/13/import-ai-431-technological-optimism-and-appropriate-fear/"}, {"text": "The issue we're talking about is there's a collective action problem here,", "context": "NPR Morning Edition interview, Sept 2026", "source_url": "https://www.nprillinois.org/2026-09-15/anthropic-co-founder-says-slowing-ai-is-a-collective-action-problem"}, {"text": "We're saying we've seen warning shots, and that gives us a window in which we can act.", "context": "NPR Morning Edition interview, Sept 2026", "source_url": "https://www.nprillinois.org/2026-09-15/anthropic-co-founder-says-slowing-ai-is-a-collective-action-problem"}], "interviews": [{"title": "Anthropic co-founder says slowing AI is a 'collective action problem'", "outlet": "NPR Morning Edition", "year": 2026, "url": "https://www.nprillinois.org/2026-09-15/anthropic-co-founder-says-slowing-ai-is-a-collective-action-problem"}, {"title": "Anthropic co-founder: 'The most powerful technology ever built'", "outlet": "Reason Podcast", "year": 2026, "url": "https://www.reason.com/podcast/2026/06/24/anthropic-co-founder-the-most-powerful-technology-ever-built/", "youtube_id": "OG3s4pojdZY"}, {"title": "Anthropic’s Co-Founder and Top Economist on Doing Research at the AI Frontier", "outlet": "Bloomberg Odd Lots", "year": 2026, "url": "https://www.bloomberg.com/news/articles/2026-06-19/anthropic-s-co-founder-and-top-economist-on-doing-research-at-the-ai-frontier"}], "links": {"website": "https://jack-clark.net/", "x": "https://x.com/jackclarkSF", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Jack_Clark_(AI_policy_expert)", "github": "", "substack": "https://importai.substack.com/"}, "p_doom_or_stance": null, "honours": null, "photo": "jack-clark.jpg"}, {"slug": "holden-karnofsky", "name": "Holden Karnofsky", "category": "lab-safety", "current_role": "Member of Technical Staff, Anthropic (advises on preparing for advanced-AI risks; Responsible Scaling Policy), reporting to Jared Kaplan (as of 2026)", "orgs_history": ["Anthropic, Member of Technical Staff (Jan 2025–)", "Carnegie Endowment for International Peace, visiting scholar (2024)", "Open Philanthropy (now Coefficient Giving), co-founder, CEO/co-CEO (2014–2023), Director of AI Strategy (2023–2024)", "OpenAI board member (2017–2021)", "GiveWell, co-founder (2007)", "Bridgewater Associates (2004–2007)"], "country": "United States", "known_for": "Co-founder of GiveWell and Open Philanthropy, author of the 'Most Important Century' series; now shapes Anthropic's Responsible Scaling Policy.", "bio": "Holden Karnofsky is an American nonprofit executive who co-founded the charity evaluator GiveWell in 2007 and the grantmaker Open Philanthropy in 2014, which under his leadership directed billions of dollars, including major early funding for AI-safety research. He sat on OpenAI's board from 2017 to 2021. On his blog Cold Takes he wrote the 'Most Important Century' series, arguing transformative AI could make this century pivotal for humanity, and essays such as 'AI Could Defeat All Of Us Combined'. After a stint as a visiting scholar at the Carnegie Endowment writing about voluntary commitments like responsible scaling policies, he joined Anthropic full-time in January 2025, where he works on its Responsible Scaling Policy, threat modelling and safety planning; he explained his views on RSP v3 in February 2026 and contributed to Claude's constitution. He is married to Anthropic president Daniela Amodei, a relationship he discloses when discussing the company.", "key_ideas": ["the most important century", "responsible scaling policies", "risk reduction per unit of 'business pain'", "AI could defeat all of us combined", "concrete, shovel-ready safety projects"], "key_works": [{"title": "The 'Most Important Century' series (Cold Takes)", "year": 2021, "url": "https://www.cold-takes.com/most-important-century/"}, {"title": "AI Could Defeat All Of Us Combined", "year": 2022, "url": "https://www.cold-takes.com/ai-could-defeat-all-of-us-combined/"}, {"title": "Responsible Scaling Policy v3 (personal take)", "year": 2026, "url": "https://www.lesswrong.com/posts/HzKuzrKfaDJvQqmjh/responsible-scaling-policy-v3"}], "quotes": [{"text": "we’re into the world where whatever your skills are, there is probably a way to use them in a way that is helping make maybe humanity’s most important event ever go better.", "context": "80,000 Hours podcast, Oct 2025", "source_url": "https://80000hours.org/podcast/episodes/holden-karnofsky-concrete-ai-safety-frontier-ai-companies/"}, {"text": "I think we should be trying to get the most risk reduction we can get per unit of business pain, or something like that - not because I intrinsically value business goals, but because I think a “balancing” attitude is ultimately better for risk reduction.", "context": "'Responsible Scaling Policy v3', LessWrong, Feb 2026", "source_url": "https://www.lesswrong.com/posts/HzKuzrKfaDJvQqmjh/responsible-scaling-policy-v3"}, {"text": "I went to Anthropic full-time in January of 2025 with the RSP as my primary focus.", "context": "'Responsible Scaling Policy v3', Feb 2026", "source_url": "https://www.lesswrong.com/posts/HzKuzrKfaDJvQqmjh/responsible-scaling-policy-v3"}, {"text": "The problem is there could be a Chernobyl for AI that we’re just unable to understand or unravel", "context": "80,000 Hours podcast, Oct 2025, on an AI incident nobody notices", "source_url": "https://80000hours.org/podcast/episodes/holden-karnofsky-concrete-ai-safety-frontier-ai-companies/"}], "interviews": [{"title": "Holden Karnofsky on dozens of opportunities to make AI safer lying on the table — and all his AGI takes", "outlet": "80,000 Hours Podcast", "year": 2025, "url": "https://80000hours.org/podcast/episodes/holden-karnofsky-concrete-ai-safety-frontier-ai-companies/"}, {"title": "Responsible Scaling Policy v3", "outlet": "LessWrong / EA Forum", "year": 2026, "url": "https://www.lesswrong.com/posts/HzKuzrKfaDJvQqmjh/responsible-scaling-policy-v3"}, {"title": "Cold Takes (blog and audio)", "outlet": "Cold Takes", "year": 2021, "url": "https://www.cold-takes.com/"}], "links": {"website": "https://www.cold-takes.com/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Holden_Karnofsky", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "holden-karnofsky.jpg"}, {"slug": "mrinank-sharma", "name": "Mrinank Sharma", "category": "lab-safety", "current_role": "Former lead of Anthropic's Safeguards Research Team (resigned 9 Feb 2026); now pursuing writing/poetry and facilitation outside the AI industry (as of 2026)", "orgs_history": ["Anthropic, Safeguards Research Team lead (Aug 2023 – Feb 2026)", "University of Oxford, DPhil in machine learning"], "country": "United Kingdom", "known_for": "Led Anthropic's Safeguards Research (sycophancy, anti-bioterror defences, an early safety case); resigned in Feb 2026 warning 'the world is in peril'.", "bio": "Mrinank Sharma completed a DPhil in machine learning at the University of Oxford and joined Anthropic in August 2023, where he led the Safeguards Research Team. His work included research on why AI assistants are sycophantic, developing and deploying defences against AI-assisted bioterrorism (including the Constitutional Classifiers line of work), writing one of the first AI safety cases, and internal transparency mechanisms; his final project studied how AI assistants could make people 'less human'. On 9 February 2026 he resigned, posting a letter on X — viewed millions of times — saying the world is in peril from 'a whole series of interconnected crises' and that he had repeatedly seen how hard it is to let values govern actions under pressure. He announced plans to return to the UK, explore a poetry degree and practise 'courageous speech', and entered a period of public silence.", "key_ideas": ["AI sycophancy", "safeguards against catastrophic misuse (bio)", "safety cases", "AI and human flourishing / dehumanisation"], "key_works": [{"title": "Towards Understanding Sycophancy in Language Models", "year": 2023, "url": "https://arxiv.org/abs/2310.13548"}, {"title": "Constitutional Classifiers: Defending against Universal Jailbreaks (co-author)", "year": 2025, "url": "https://arxiv.org/abs/2501.18837"}, {"title": "Why I Left Anthropic", "year": 2026, "url": "https://mrinank.substack.com/p/why-i-left-anthropic"}], "quotes": [{"text": "The world is in peril. And not just from Al, or bioweapons, but from a whole series of interconnected crises unfolding in this very moment.", "context": "Resignation letter, 9 Feb 2026 (Business Insider transcription renders 'AI' as 'Al')", "source_url": "https://www.businessinsider.com/read-exit-letter-by-an-anthropic-ai-safety-leader-2026-2"}, {"text": "We appear to be approaching a threshold where our wisdom must grow in equal measure to our capacity to affect the world, lest we face the consequences.", "context": "Resignation letter, Feb 2026", "source_url": "https://www.businessinsider.com/read-exit-letter-by-an-anthropic-ai-safety-leader-2026-2"}, {"text": "Moreover, throughout my time here, I've repeatedly seen how hard it is to truly let our values govern our actions.", "context": "Resignation letter, Feb 2026", "source_url": "https://www.businessinsider.com/read-exit-letter-by-an-anthropic-ai-safety-leader-2026-2"}, {"text": "I didn’t expect my letter to be shared as widely as it was, or to be of interest to so many people.", "context": "'Why I Left Anthropic', Substack, 15 Feb 2026", "source_url": "https://mrinank.substack.com/p/why-i-left-anthropic"}], "interviews": [{"title": "Read the Letter an Anthropic AI Safety Leader Used to Announce Exit", "outlet": "Business Insider", "year": 2026, "url": "https://www.businessinsider.com/read-exit-letter-by-an-anthropic-ai-safety-leader-2026-2"}, {"title": "Anthropic AI safety researcher quits with 'world in peril' warning", "outlet": "BBC News", "year": 2026, "url": "https://www.bbc.com/news/articles/c62dlvdq3e3o"}, {"title": "Why I Left Anthropic", "outlet": "living more whole (Substack)", "year": 2026, "url": "https://mrinank.substack.com/p/why-i-left-anthropic"}], "links": {"website": "", "x": "https://x.com/MrinankSharma", "scholar": "", "wikipedia": "", "github": "", "substack": "https://mrinank.substack.com/"}, "p_doom_or_stance": null, "honours": null, "photo": "mrinank-sharma.jpg"}, {"slug": "collin-burns", "name": "Collin Burns", "category": "lab-safety", "current_role": "AI researcher; briefly named director of the US Center for AI Standards and Innovation (CAISI) in April 2026 but pushed out after four days; current affiliation not publicly confirmed (as of Oct 2026)", "orgs_history": ["US Commerce Dept CAISI, director-designate (Apr 2026, 4 days)", "Anthropic, Member of Technical Staff (Dec 2024 – Apr 2026)", "OpenAI, technical lead of the Superalignment generalization team (2023–2024)", "UC Berkeley, PhD student under Jacob Steinhardt & Dan Klein (left early)", "Columbia University, BA"], "country": "United States", "known_for": "Lead author of OpenAI's Weak-to-Strong Generalization and of 'Discovering Latent Knowledge'; co-author of MMLU and MATH.", "bio": "Collin Burns is an American AI alignment researcher who studied at Columbia and began a PhD at UC Berkeley with Jacob Steinhardt and Dan Klein, co-authoring the influential MMLU and MATH benchmarks with Dan Hendrycks. His 2022 paper 'Discovering Latent Knowledge in Language Models Without Supervision' proposed finding truth-like directions in model activations without labels. He left Berkeley early for OpenAI, where he was technical lead of the Superalignment generalization team and lead author of 'Weak-to-Strong Generalization' (2023), which tested whether weak supervisors can elicit strong models' capabilities — an analogy for humans supervising superhuman AI. He joined Anthropic in late 2024 and mentored Anthropic Fellows. In April 2026 the Commerce Department picked him to lead the Center for AI Standards and Innovation, but the White House pushed him out within days, reportedly over his Anthropic ties, and named Chris Fall instead. (Not to be confused with the speedcuber Collin Burns.)", "key_ideas": ["weak-to-strong generalization", "unsupervised elicitation of latent knowledge", "honesty / truthfulness directions", "superhuman supervision problem"], "key_works": [{"title": "Measuring Massive Multitask Language Understanding (MMLU)", "year": 2020, "url": "https://arxiv.org/abs/2009.03300"}, {"title": "Discovering Latent Knowledge in Language Models Without Supervision", "year": 2022, "url": "https://arxiv.org/abs/2212.03827"}, {"title": "Weak-to-Strong Generalization: Eliciting Strong Capabilities With Weak Supervision", "year": 2023, "url": "https://arxiv.org/abs/2312.09390"}], "quotes": [{"text": "One of the main motivations for our team is that AI systems are becoming much more capable very quickly.", "context": "OpenAI Forum talk 'Weak to Strong Generalization', Feb 2024 (speaker inferred as Burns, who presented first; transcript garbles names)", "source_url": "https://forum.openai.com/en/public/videos/weak-to-strong-generalization-2024-replay", "unverified": true}, {"text": "One important consequence of substantially smarter models is that evaluating the behavior of these models becomes increasingly difficult over time.", "context": "Same OpenAI Forum talk, Feb 2024 (speaker attribution inferred)", "source_url": "https://forum.openai.com/en/public/videos/weak-to-strong-generalization-2024-replay", "unverified": true}, {"text": "And this is important for alignment in particular, because right now, our core alignment techniques, for example, reinforcement learning from human feedback, or LHF, fundamentally relies on reliable human supervision.", "context": "Same talk, Feb 2024 ('LHF' is the transcript's rendering of RLHF; speaker attribution inferred)", "source_url": "https://forum.openai.com/en/public/videos/weak-to-strong-generalization-2024-replay", "unverified": true}], "interviews": [{"title": "Weak to Strong Generalization (talk, with Pavel Izmailov)", "outlet": "OpenAI Forum", "year": 2024, "url": "https://forum.openai.com/en/public/videos/weak-to-strong-generalization-2024-replay"}, {"title": "Trump Admin Fires Researcher Days Into New Job Over Anthropic Ties", "outlet": "PCMag", "year": 2026, "url": "https://me.pcmag.com/en/ai/36780/trump-admin-axes-former-anthropic-researcher-leading-ai-safety-body"}, {"title": "White House pushed out new AI official after just four days on the job", "outlet": "The Washington Post", "year": 2026, "url": "https://www.washingtonpost.com/technology/2026/04/24/white-house-fires-ai-official-anthropic"}], "links": {"website": "https://collinpburns.com/", "x": "", "scholar": "https://scholar.google.com/citations?user=JGS2xjkAAAAJ", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "collin-burns.jpg"}, {"slug": "william-saunders", "name": "William Saunders", "category": "lab-safety", "current_role": "Researcher, Alignment Science team, Anthropic (joined 2025; as of 2026)", "orgs_history": ["Anthropic, Alignment Science (2025–)", "METR, technical staff (2024, former)", "OpenAI, Alignment and Superalignment teams (2021–Feb 2024)", "Ought; Google (software engineer / ML researcher)"], "country": "", "known_for": "Ex-OpenAI superalignment researcher who quit rather than work on 'the Titanic of AI' and testified to the US Senate on lab safety and security.", "bio": "William Saunders is an AI safety researcher with a master's in computer science from the University of Waterloo who worked at Google and Ought before joining OpenAI in 2021. On OpenAI's Alignment and Superalignment teams he worked on scalable oversight — including AI-written critiques to help humans spot model mistakes — and interpretability, and co-authored WebGPT and Codex papers. He resigned in February 2024, later saying he 'didn't want to end up working for the Titanic of AI'. He co-signed the June 2024 'Right to Warn' letter, and in September 2024 testified before the Senate Judiciary subcommittee that AGI could plausibly arrive in as little as three years, that OpenAI had repeatedly prioritised deployment over rigour, and that security vulnerabilities would have let hundreds of engineers steal models such as GPT-4. He briefly worked at METR and joined Anthropic's alignment team in 2025.", "key_ideas": ["scalable oversight via AI critiques", "whistleblower protections for AI workers", "third-party testing and transparency", "lab security"], "key_works": [{"title": "Self-critiquing models for assisting human evaluators", "year": 2022, "url": "https://arxiv.org/abs/2206.05802"}, {"title": "WebGPT: Browser-assisted question-answering with human feedback (co-author)", "year": 2021, "url": "https://arxiv.org/abs/2112.09332"}, {"title": "Written testimony, Senate Judiciary hearing 'Oversight of AI: Insiders' Perspectives'", "year": 2024, "url": "https://www.judiciary.senate.gov/imo/media/doc/2024-09-17_pm_-_testimony_-_saunders.pdf"}], "quotes": [{"text": "I resigned from OpenAI because I lost faith that by themselves they will make responsible decisions about AGI.", "context": "US Senate Judiciary subcommittee testimony, 17 Sept 2024", "source_url": "https://www.judiciary.senate.gov/imo/media/doc/2024-09-17_pm_-_testimony_-_saunders.pdf"}, {"text": "There are still significant gaps to close but I believe it is plausible that an AGI system could be built in as little as three years.", "context": "Senate testimony, Sept 2024", "source_url": "https://www.judiciary.senate.gov/imo/media/doc/2024-09-17_pm_-_testimony_-_saunders.pdf"}, {"text": "No one knows how to ensure that AGI systems will be safe and controlled.", "context": "Senate testimony, Sept 2024", "source_url": "https://www.judiciary.senate.gov/imo/media/doc/2024-09-17_pm_-_testimony_-_saunders.pdf"}, {"text": "While OpenAI has pioneered aspects of this testing, they have also repeatedly prioritized deployment over rigor.", "context": "Senate testimony, Sept 2024", "source_url": "https://www.judiciary.senate.gov/imo/media/doc/2024-09-17_pm_-_testimony_-_saunders.pdf"}, {"text": "I really didn't want to end up working for the Titanic of AI.", "context": "Big Technology podcast, 2024, as cited by Ethical AI Departures", "source_url": "https://ethicalaidepartures.fyi/profiles/william-saunders"}], "interviews": [{"title": "Oversight of AI: Insiders' Perspectives (Senate Judiciary hearing testimony)", "outlet": "US Senate", "year": 2024, "url": "https://www.judiciary.senate.gov/imo/media/doc/2024-09-17_pm_-_testimony_-_saunders.pdf"}, {"title": "Former OpenAI employee quit to avoid 'working for the Titanic of AI' (on Big Technology Podcast)", "outlet": "Cointelegraph", "year": 2024, "url": "https://cointelegraph.com/news/open-ai-artificial-intelligence-safety-employee-quit-titanic"}, {"title": "AIWI — supporting concerned AI employees (testimonial)", "outlet": "AIWI", "year": 2025, "url": "https://aiwi.org/"}], "links": {"website": "", "x": "", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "william-saunders.jpg"}, {"slug": "ilya-sutskever", "name": "Ilya Sutskever", "category": "lab-safety", "current_role": "Co-founder and CEO, Safe Superintelligence Inc. (SSI) (CEO since July 2025; as of 2026)", "orgs_history": ["Safe Superintelligence Inc. co-founder (June 2024–), CEO (July 2025–)", "OpenAI co-founder & Chief Scientist (2015–2024); Superalignment co-lead (2023–24); board member until Nov 2023", "Google Brain research scientist (2013–2015)", "DNNresearch co-founder (2012)"], "country": "Israel / Canada (born in Russia)", "known_for": "Co-creator of AlexNet and seq2seq, OpenAI's chief scientist behind GPT and o1, now building 'safe superintelligence' at SSI.", "bio": "Ilya Sutskever is a Soviet-born Israeli-Canadian computer scientist who studied under Geoffrey Hinton and co-created AlexNet in 2012. At Google Brain he co-invented sequence-to-sequence learning, then co-founded OpenAI in 2015 as chief scientist, overseeing the research behind the GPT models and ChatGPT and leading work that produced reasoning models such as o1. In July 2023 he co-led OpenAI's Superalignment team with Jan Leike; that November he was among the board members who briefly ousted Sam Altman, later saying he regretted it. He left in May 2024 and in June co-founded Safe Superintelligence Inc. with Daniel Gross and Daniel Levy, a lab whose 'first product will be the safe superintelligence'. He became SSI's CEO in July 2025 after Gross left for Meta. In 2025 he argued the field is moving 'from the age of scaling to the age of research' and that labs should aim for AI 'robustly aligned to care about sentient life'. In July 2026 SSI announced a long-term compute partnership with NVIDIA, reportedly worth about $5 billion.", "key_ideas": ["safe superintelligence as a single product", "generalization as the core unsolved problem", "age of scaling → age of research", "AI that cares about sentient life", "incremental deployment"], "key_works": [{"title": "ImageNet Classification with Deep Convolutional Neural Networks (AlexNet)", "year": 2012, "url": "https://papers.nips.cc/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html"}, {"title": "Sequence to Sequence Learning with Neural Networks", "year": 2014, "url": "https://arxiv.org/abs/1409.3215"}, {"title": "Introducing Superalignment (with Jan Leike)", "year": 2023, "url": "https://openai.com/index/introducing-superalignment/"}, {"title": "Weak-to-Strong Generalization", "year": 2023, "url": "https://arxiv.org/abs/2312.09390"}], "quotes": [{"text": "It’s the AI that’s robustly aligned to care about sentient life specifically.", "context": "Dwarkesh Podcast, Nov 2025, on what labs should aspire to build", "source_url": "https://www.dwarkesh.com/p/ilya-sutskever-2"}, {"text": "One of the ways in which my thinking has been changing is that I now place more importance on AI being deployed incrementally and in advance.", "context": "Dwarkesh Podcast, Nov 2025", "source_url": "https://www.dwarkesh.com/p/ilya-sutskever-2"}, {"text": "But now that compute is big, compute is now very big, in some sense we are back to the age of research.", "context": "Dwarkesh Podcast, Nov 2025", "source_url": "https://www.dwarkesh.com/p/ilya-sutskever-2"}, {"text": "These models somehow just generalize dramatically worse than people. It's a very fundamental thing.", "context": "Dwarkesh Podcast, Nov 2025 (pull quote)", "source_url": "https://www.dwarkesh.com/p/ilya-sutskever-2"}, {"text": "Pre-training as we know it will unquestionably end", "context": "NeurIPS 2024 talk, Vancouver, as reported by The Verge", "source_url": "https://www.theverge.com/2024/12/13/24320811/what-ilya-sutskever-sees-openai-model-data-training"}, {"text": "We’ve achieved peak data and there’ll be no more", "context": "NeurIPS 2024 talk, as reported by The Verge", "source_url": "https://www.theverge.com/2024/12/13/24320811/what-ilya-sutskever-sees-openai-model-data-training"}], "interviews": [{"title": "Ilya Sutskever — We're moving from the age of scaling to the age of research", "outlet": "Dwarkesh Podcast", "year": 2025, "url": "https://www.dwarkesh.com/p/ilya-sutskever-2", "youtube_id": "aR20FWCCjAs"}, {"title": "Ilya Sutskever (OpenAI Chief Scientist) - Building AGI, Alignment, & Future Models", "outlet": "Dwarkesh Podcast", "year": 2023, "url": "https://www.dwarkesh.com/p/ilya-sutskever", "youtube_id": "Yf1o0TQzry8"}, {"title": "#94 - Ilya Sutskever: Deep Learning", "outlet": "Lex Fridman Podcast", "year": 2020, "url": "https://lexfridman.com/ilya-sutskever/", "youtube_id": "13CZPWmke6A"}, {"title": "NeurIPS 2024 Test of Time talk (coverage: 'OpenAI cofounder Ilya Sutskever says the way AI is built is about to change')", "outlet": "The Verge", "year": 2024, "url": "https://www.theverge.com/2024/12/13/24320811/what-ilya-sutskever-sees-openai-model-data-training"}], "links": {"website": "https://ssi.inc/", "x": "https://x.com/ilyasut", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Ilya_Sutskever", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "ilya-sutskever.jpg"}, {"slug": "lilian-weng", "name": "Lilian Weng", "category": "lab-safety", "current_role": "Leads a top-level OpenAI team accelerating internal research, including recursive self-improvement (rejoined OpenAI July 2026; as of Oct 2026)", "orgs_history": ["OpenAI, research lead for accelerating internal research / RSI (Jul 2026–)", "Thinking Machines Lab, co-founder (2025 – Jul 2026)", "OpenAI, VP of Research (Safety) & Head of Safety Systems (2021–Nov 2024); robotics and Applied AI Research (2018–2021)", "Facebook, Dropbox, Affirm"], "country": "China (born); based in the United States", "known_for": "Built and led OpenAI's Safety Systems; author of the widely read Lil'Log technical blog (reward hacking, hallucination, adversarial attacks).", "bio": "Lilian Weng studied information systems and computer science at Peking University and earned a PhD at Indiana University Bloomington in 2014, then worked at Facebook, Dropbox and Affirm. She joined OpenAI in 2018, working on robotics before building the Applied AI Research team and, from 2021, leading Safety Systems — the engineers and researchers responsible for deployment safety, moderation tooling and misuse defences — eventually as VP of Research, Safety. She left OpenAI in November 2024 and in 2025 co-founded Thinking Machines Lab with Mira Murati. Her blog Lil'Log, running since 2017, is a standard reference for AI researchers, with deep surveys on reward hacking, hallucination, adversarial attacks on LLMs and, in 2026, harness engineering for self-improvement. In late July 2026 she stepped down from Thinking Machines citing health and workload, and returned to OpenAI to lead a team focused on accelerating internal research, including recursive self-improvement.", "key_ideas": ["deployment safety systems", "reward hacking", "LLM hallucination", "adversarial attacks on LLMs", "recursive self-improvement harnesses"], "key_works": [{"title": "Reward Hacking in Reinforcement Learning (Lil'Log)", "year": 2024, "url": "https://lilianweng.github.io/posts/2024-11-28-reward-hacking/"}, {"title": "Extrinsic Hallucinations in LLMs (Lil'Log)", "year": 2024, "url": "https://lilianweng.github.io/posts/2024-07-07-hallucination/"}, {"title": "Adversarial Attacks on LLMs (Lil'Log)", "year": 2023, "url": "https://lilianweng.github.io/posts/2023-10-25-adv-attack-llm/"}, {"title": "Harness Engineering for Self-Improvement (Lil'Log)", "year": 2026, "url": "https://lilianweng.github.io/posts/2026-07-04-harness/"}], "quotes": [{"text": "Reward hacking occurs when a reinforcement learning (RL) agent exploits flaws or ambiguities in the reward function to achieve high rewards, without genuinely learning or completing the intended task.", "context": "Lil'Log, 'Reward Hacking in Reinforcement Learning', Nov 2024", "source_url": "https://lilianweng.github.io/posts/2024-11-28-reward-hacking/"}, {"text": "Instances where the model learns to modify unit tests to pass coding tasks, or where responses contain biases that mimic a user’s preference, are pretty concerning and are likely one of the major blockers for real-world deployment of more autonomous use cases of AI models.", "context": "Same post, Nov 2024", "source_url": "https://lilianweng.github.io/posts/2024-11-28-reward-hacking/"}, {"text": "I don’t feel I’m able to continue at the pace a startup requires,", "context": "Message to Thinking Machines colleagues, shared on X, July 2026 (via TechCrunch)", "source_url": "https://techcrunch.com/2026/07/29/thinking-machines-co-founder-lilian-weng-left-the-company-citing-health-reasons-then-joined-openai/"}, {"text": "The future worth building is human.", "context": "X post on leaving Thinking Machines, 27 July 2026 (embedded in TechCrunch)", "source_url": "https://techcrunch.com/2026/07/29/thinking-machines-co-founder-lilian-weng-left-the-company-citing-health-reasons-then-joined-openai/"}], "interviews": [{"title": "Thinking Machines co-founder Lilian Weng left the company citing health reasons, then joined OpenAI", "outlet": "TechCrunch", "year": 2026, "url": "https://techcrunch.com/2026/07/29/thinking-machines-co-founder-lilian-weng-left-the-company-citing-health-reasons-then-joined-openai/"}, {"title": "Lilian Weng Returns to OpenAI After Leaving Thinking Machines Lab", "outlet": "Business Insider", "year": 2026, "url": "https://www.businessinsider.com/lilian-weng-returns-to-openai-after-leaving-thinking-machines-lab-2026-7"}, {"title": "People Moves: Lilian Weng, OpenAI", "outlet": "AI Magazine", "year": 2026, "url": "https://aimagazine.com/articles/people-moves-lilian-weng-openai"}], "links": {"website": "https://lilianweng.github.io/", "x": "https://x.com/lilianweng", "scholar": "", "wikipedia": "", "github": "https://github.com/lilianweng", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "lilian-weng.jpg"}]);
